def evaluate_technicians(technicians):
    SCORE_RANGE = {
        (1, 5): 1,
        (6, 10): 2,
        (11, 15): 3,
        16: 4,
    }

    score = 0

    # Evaluate problem-solving skills
    score += SCORE_RANGE.get(
        get_range(technicians.problem_solving_skills), 0
    )

    # Evaluate safety awareness
    score += SCORE_RANGE.get(
        get_range(technicians.safety_awareness), 0
    )

    # Evaluate technical knowledge
    score += SCORE_RANGE.get(
        get_range(technicians.technical_knowledge), 0
    )

    # Evaluate attention to detail
    score += SCORE_RANGE.get(
        get_range(technicians.attention_to_detail), 0
    )

    # Evaluate gender
    if technicians.gender == 'male':
        score += 2

    return score

def get_range(value):
    for (min_val, max_val), score in SCORE_RANGE.items():
        if min_val <= value <= max_val:
            return (min_val, max_val)
    return (-1, -1)

