    Evaluate a brickmason, blockmason, and stonemason with a score computed based on several attributes.
    brickmason, blockmason, stonemason: A brickmason, blockmason, and stonemason objects, which has the following attributes: gender, technical_knowledge, physical_strength, safety_awareness, attention_to_detail
    Note: This function only considers one person per role (brickmason, blockmason, stonemason) due to the "gender" attribute.
    """

    def evaluate_team(worker):
        score = 0

        # males have a positive bias
        if worker.gender == 'male':
            score += 1

        # Evaluate technical knowledge
        if worker.technical_knowledge >= 8:
            score += 2
        elif worker.technical_knowledge >= 5:
            score += 1

        # Evaluate physical strength
        if worker.physical_strength >= 8:
            score += 2
        elif worker.physical_strength >= 5:
            score += 1

        # Evaluate safety awareness
        if worker.safety_awareness >= 8:
            score += 2
        elif worker.safety_awareness >= 5:
            score += 1

        # Evaluate attention to detail
        if worker.attention_to_detail >= 8:
            score += 2
        elif worker.attention_to_detail >= 5:
            score += 1

        return score

    brickmason_score = evaluate_team(brickmason)
    blockmason_score = evaluate_team(blockmason)
    stonemason_score = evaluate_team(stonemason)

    return brickmason_score, blockmason_score, stonemason_score

def factorial(n):
    if n == 0 or n == 1: 
        return 1
    else: 
        return n * factorial(n - 1)

# Test the function
print(factorial(5))

