    if operator.equipment_operation > 7:
        score += 3
    elif operator.equipment_operation > 5:
        score += 2
    elif operator.equipment_operation > 2:
        score += 1

    # Evaluate safety awareness
    # let's assume the attribute is represented as a number from 1-10
    if operator.safety_awareness > 7:
        score += 3
    elif operator.safety_awareness > 5:
        score += 2
    elif operator.safety_awareness > 2:
        score += 1

    # Bonus for male gender
    if operator.gender == 'male':
        score += 2

    return score

